<script>import {onMount} from 'svelte';import {incidents,errors,loadResource,actIncident,notify,auth,clock,snapshot} from '../state.js';import Badge from '../components/Badge.svelte';import Icon from '../components/Icon.svelte';import {date,sessionGet,sessionSet} from '../lib.js';let filter=sessionGet('alerts.filter','active'),search=sessionGet('alerts.search',''),busy='';$: sessionSet('alerts.filter',filter);$: sessionSet('alerts.search',search);$: shown=$incidents.filter(i=>(filter==='all'||(filter==='resolved'?!!i.resolved_at:!i.resolved_at))&&(i.message+' '+i.node).toLowerCase().includes(search.toLowerCase()));onMount(()=>loadResource('incidents'));async function action(i,a,m=60){busy=i.id;try{await actIncident(i.id,a,m);}catch(e){notify(e.message,'error');}finally{busy='';}}</script>
<section class="panel"><div class="toolbar"><div class="tabs"><button class:active={filter==='active'} onclick={()=>filter='active'}>アクティブ</button><button class:active={filter==='resolved'} onclick={()=>{filter='resolved';loadResource('incidents',true);}}>復旧済み</button><button class:active={filter==='all'} onclick={()=>{filter='all';loadResource('incidents',true);}}>すべて</button></div><label class="search"><Icon name="search" size={16}/><input bind:value={search} placeholder="ノード・内容で検索" aria-label="アラート検索"/></label><button onclick={()=>loadResource('incidents',true)}><Icon name="refresh" size={14}/>履歴を更新</button></div>
{#if $errors.incidents}<p class="notice warning">{$errors.incidents}</p>{/if}
<div class="incident-list">{#each shown as i (i.id)}<article class="incident"><div class="incident-top"><Badge state={i.resolved_at?'healthy':i.severity} text={i.resolved_at?'復旧済み':''}/><span class="quiet">観測元: {i.observer}</span><time>{date(i.opened_at)}</time></div><h3>{i.message}</h3><div class="incident-bottom"><div class="quiet">{i.acknowledged?'確認済み · ':''}{i.silenced_until&&Date.parse(i.silenced_until)>$clock?'通知停止中（'+date(i.silenced_until)+'まで）':i.last_notified_at?'最終通知 '+date(i.last_notified_at):'通知未送信'}{#if i.delivery_error}<span class="error-text"> · {i.delivery_error}</span>{/if}</div>{#if !i.resolved_at}<div class="button-group"><button disabled={!$auth?.authenticated||busy===i.id} onclick={()=>action(i,'ack')}>確認済みにする</button><button disabled={!$auth?.authenticated||busy===i.id} onclick={()=>action(i,'snooze',60)}>通知を1時間停止</button>{#if i.acknowledged||i.silenced_until}<button disabled={!$auth?.authenticated||busy===i.id} onclick={()=>action(i,'resume')}>通知を再開</button>{/if}</div>{/if}</div></article>{:else}<div class="empty compact-empty"><Icon name="check" size={28}/><h3>該当するアラートはありません</h3><p>確認済み・通知停止は、障害の復旧とは別に管理します。</p></div>{/each}</div></section>
<p class="hint">この観測ノードの履歴です。複数ノードが通知する構成では観測元を併記します。別ノードの通知停止や全体共通の確認済み状態としては同期しません。</p>
